  "impactedApis": [
    {
      "endpoint": "GET /api/links/{code}/analytics",
      "change": "New endpoint returning HTTP 200 for an existing code with totalClicks, exactly 30 calendar-day click buckets, and at most five ordered non-empty referrers; it retains the existing 404 not-found behavior.",
      "backwardCompatible": true
    },
    {
      "endpoint": "POST /api/links",
      "change": "Existing successful response and ordinary invalid-URL response remain unchanged, but destinations longer than 2048 characters and destinations targeting the configured shortener origin and redirect path are rejected with the existing invalid-URL status and detail.",
      "backwardCompatible": true
    },
    {
      "endpoint": "GET /{code}",
      "change": "Existing 302 redirect and Location response remain unchanged; each successful redirect additionally persists a timestamped event and optional Referer.",
      "backwardCompatible": true
    },
    {
      "endpoint": "GET /api/links/{code}",
      "change": "No response contract change; clickCount remains the existing link counter and continues to represent successful redirects.",
      "backwardCompatible": true
    }
  ],
  "dataChanges": [
    {
      "entity": "RedirectEvent",
      "change": "Add a new persisted table/entity with an identifier, link relationship, event timestamp, and nullable or blank-safe referrer column.",
      "migrationImpact": "Requires schema creation in deployed environments. Existing links and historical redirects are not backfilled; analytics begins at deployment."
    },
    {
      "entity": "Link",
      "change": "Add the relationship metadata needed to associate redirect events with links, while retaining originalUrl, clickCount, and existing constraints.",
      "migrationImpact": "Relationship is additive and compatible with existing link rows."
    },
    {
      "entity": "AuditEvent",
      "change": "Reuse the existing audit trail for analytics requests and classified creation rejections; only widen or adjust constraints if required by the selected action/outcome values.",
      "migrationImpact": "Normally no data migration is required; existing audit rows remain readable."
    },
    {
      "entity": "Analytics query projections",
      "change": "Add database query projections for total counts, date-bounded daily grouping, and top-five referrer aggregation.",
      "migrationImpact": "No externally visible schema contract; query date grouping must use the configured server timezone consistently with persisted timestamps."
    }
  ],
  "testsToUpdate": [
    {
      "path": "src/test/java/com/example/shortener/UrlShortenerHttpIntegrationTest.java",
      "change": "Add assertions for redirect-event rows, Referer and missing-Referer handling, analytics JSON and 30 buckets, top-five ordering, analytics audit/log entries, self-link rejection independent of request Host, and over-2048 rejection without persistence."
    },
    {
      "path": "src/test/java/com/example/shortener/service/LinkServiceTest.java",
      "change": "Update constructor mocks and verify exactly one event is saved per successful resolve, including request Referer, while preserving click-count and existing audit assertions."
    },
    {
      "path": "src/test/java/com/example/shortener/service/UrlValidatorTest.java",
      "change": "Cover exact and normalized configured-origin self-links, unrelated origins, redirect-path targeting, and the existing invalid-URL message for overlong destinations."
    },
    {
      "path": "src/test/java/com/example/shortener/service/ShortCodeAndUrlBuilderTest.java",
      "change": "Replace request-derived fallback expectations with configured server-origin expectations and test configured app.public-origin normalization."
    },
    {
      "path": "src/test/java/com/example/shortener/controller/GlobalExceptionHandlerTest.java",
      "change": "Verify rejection reasons are audited safely while the HTTP problem response remains unchanged."
    },
    {
      "path": "src/test/java/com/example/shortener/service/AnalyticsServiceTest.java",
      "change": "Create unit coverage for aggregation mapping, date range construction, zero-count days, referrer filtering, not-found outcomes, and audit/log calls."
    },
    {
      "path": "src/test/java/com/example/shortener/repository/RedirectEventRepositoryTest.java",
      "change": "Create repository integration coverage proving aggregation and limits execute through database queries rather than application-side event loading."
    }
  ],
  "risks": [
    "Adding redirect-event persistence to the redirect transaction can cause a previously successful redirect to fail if event persistence fails; this is required to avoid silently returning success without analytics.",
    "Concurrent redirects must continue to update clickCount safely while independently inserting one event per redirect; incorrect transaction boundaries could lose events or counts.",
    "Database-specific date truncation or grouping functions may behave differently across H2 and production databases, especially around timezone conversion and calendar-day boundaries.",
    "Origin normalization errors involving default ports, case, trailing slashes, encoded paths, or IPv6 literals could either permit a redirect loop or reject an unrelated destination.",
    "A missing or unusable configured public origin could make self-link validation ineffective or make generated short URLs unusable; deployment configuration must supply a server-side fallback host/origin.",
    "Analytics query projections and referrer columns can become performance hotspots without suitable indexes on link foreign key, event timestamp, and referrer.",
    "Existing tests or clients that assume clickCount is the sole redirect persistence mechanism may observe timing or transaction changes even though the response shape remains unchanged.",
    "Analytics output depends on the configured server timezone; changing that configuration changes day bucket boundaries but is necessary for consistent calendar-day semantics."
  ],
  "decisions": [
    {
      "title": "Use a dedicated RedirectEvent entity and repository",
      "rationale": "The requirement needs one immutable event per redirect and database-side aggregation without loading all events into memory.",
      "alternatives": [
        "Store only aggregate counters on Link, which cannot provide timestamps or referrers.",
        "Store events as an unstructured audit payload, which would make analytics queries and referential integrity inappropriate."
      ]
    },
    {
      "title": "Keep the existing Link clickCount",
      "rationale": "Existing details responses and clients depend on clickCount, so the new event count should not replace the existing response field.",
      "alternatives": [
        "Compute clickCount dynamically from redirect events, which risks changing existing behavior and response timing.",
        "Remove clickCount, which violates the compatibility requirement."
      ]
    },
    {
      "title": "Return totalClicks, clicksPerDay, and topReferrers",
      "rationale": "This follows the approved requirements assumption and provides exactly 30 zero-filled daily buckets plus at most five referrer entries.",
      "alternatives": [
        "Return only days with clicks, which would violate the requirement for exactly 30 buckets.",
        "Return raw redirect events, which violates the bounded database-backed analytics requirement."
      ]
    },
    {
      "title": "Use configured app.public-origin and never request Host",
      "rationale": "The request Host header is attacker-controlled in many deployments and cannot safely define whether a destination loops back to the shortener.",
      "alternatives": [
        "Continue deriving the origin from HttpServletRequest, which is explicitly forbidden.",
        "Perform DNS or network alias resolution, which is outside scope and introduces availability and security concerns."
      ]
    },
    {
      "title": "Treat missing or blank Referer as excluded from topReferrers",
      "rationale": "Such redirects still count toward total and daily metrics, while the requirement specifies only non-empty referrers in the top-five list.",
      "alternatives": [
        "Use a synthetic '(none)' referrer entry, which would alter the requested top-referrer contract.",
        "Discard the redirect event, which would make total clicks incorrect."
      ]
    },
    {
      "title": "Use server-configured timezone and persisted instants",
      "rationale": "Persisted timestamps remain consistent while daily grouping follows the configured calendar-day definition.",
      "alternatives": [
        "Use the database default timezone, which may differ between deployments.",
        "Use the request timezone, which is unavailable or untrusted."
      ]
    },
    {
      "title": "Reuse the existing invalid-URL response for both new rejection types",
      "rationale": "The requirement explicitly requires self-links and over-long destinations to preserve the existing invalid-URL status and response contract.",
      "alternatives": [
        "Introduce separate validation status codes, which would break the stated compatibility requirement.",
        "Expose detailed destination values in errors or logs, which risks leaking sensitive URL data."
      ]
    },
    {
      "title": "Reuse the existing audit trail with classified actions or outcomes",
      "rationale": "The repository already audits creation failures and operational outcomes, so additive reuse preserves compliance visibility and avoids a second audit store.",
      "alternatives": [
        "Create a separate analytics audit table, which duplicates existing audit infrastructure.",
        "Log only and omit audit persistence, which fails the explicit audit requirement."
      ]
    }
  ]
