"},{"path":"src/main/java/com/example/shortener/service/UrlValidator.java","content":"package com.example.shortener.service;

import com.example.shortener.exception.InvalidUrlException;
import java.net.URI;
import java.net.URISyntaxException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class UrlValidator {
    private static final Logger log = LoggerFactory.getLogger(UrlValidator.class);
    private static final int MAX_URL_LENGTH = 2048;
    private final String publicOrigin;

    public UrlValidator() {
        this("http://localhost:8080");
    }

    @Autowired
    public UrlValidator(@Value("${app.public-origin:http://localhost:8080}") String publicOrigin) {
        this.publicOrigin = publicOrigin == null || publicOrigin.isBlank()
                ? "http://localhost:8080" : publicOrigin;
    }

    public void validate(String value) {
        if (value == null || value.isBlank()) {
            reject("INVALID_URL");
        }
        if (value.length() > MAX_URL_LENGTH) {
            reject("URL_TOO_LONG");
        }
        try {
            URI uri = new URI(value);
            String scheme = uri.getScheme();
            if (!uri.isAbsolute() || scheme == null
                    || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))
                    || uri.getAuthority() == null || uri.getHost() == null || uri.getHost().isBlank()) {
                reject("INVALID_URL");
            }
            URI origin = new URI(publicOrigin);
            if (sameOrigin(uri, origin) && isRedirectPath(uri.getPath())) {
                reject("SELF_LINK");
            }
        } catch (URISyntaxException | IllegalArgumentException ex) {
            reject("INVALID_URL");
        }
    }

    private boolean sameOrigin(URI first, URI second) {
        return first.getScheme().equalsIgnoreCase(second.getScheme())
                && first.getHost().equalsIgnoreCase(second.getHost())
                && effectivePort(first) == effectivePort(second);
    }

    private int effectivePort(URI uri) {
        if (uri.getPort() >= 0) {
            return uri.getPort();
        }
        return "https".equalsIgnoreCase(uri.getScheme()) ? 443 : 80;
    }

    private boolean isRedirectPath(String path) {
        return path == null || path.isEmpty() || path.equals("/")
                || path.matches("/[A-Za-z0-9_-]{7}");
    }

    private void reject(String reason) {
        log.warn("CREATION_REJECTED outcome={}", reason);
        throw new InvalidUrlException("url must be an absolute HTTP or HTTPS URL", reason);
    }
}
