"},{"path":"src/test/java/com/example/shortener/service/LinkAnalyticsServiceTest.java","content":"package com.example.shortener.service;

import com.example.shortener.api.AnalyticsResponse;
import com.example.shortener.domain.Link;
import com.example.shortener.exception.LinkNotFoundException;
import com.example.shortener.repository.LinkRepository;
import com.example.shortener.repository.RedirectEventRepository;
import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.data.domain.Pageable;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class LinkAnalyticsServiceTest {
    @Mock LinkRepository links;
    @Mock RedirectEventRepository events;
    @Mock AuditService audit;
    @Mock HttpServletRequest request;

    @Test
    void aggregatesDatabaseProjectionsIntoThirtyBucketsAndFiveReferrers() {
        Link link = mock(Link.class);
        when(link.getId()).thenReturn(42L);
        when(links.findByCode("ABC1234")).thenReturn(Optional.of(link));
        when(events.countByLinkId(42L)).thenReturn(17L);

        LocalDate today = LocalDate.now();
        RedirectEventRepository.DailyProjection todayRow = daily(today, 3L);
        RedirectEventRepository.DailyProjection olderRow = daily(today.minusDays(2), 4L);
        when(events.countByDay(eq(42L), eq(today.minusDays(29)), eq(today)))
                .thenReturn(List.of(olderRow, todayRow));
        when(events.topReferrers(eq(42L), any(Pageable.class)))
                .thenReturn(List.of(referrer("https://one.example", 8L), referrer("https://two.example", 4L)));

        LinkAnalyticsService service = new LinkAnalyticsService(links, events, audit, "UTC");
        AnalyticsResponse response = service.analytics("ABC1234", request);

        assertThat(response.totalClicks()).isEqualTo(17L);
        assertThat(response.clicksPerDay()).hasSize(30);
        assertThat(response.clicksPerDay().get(0).date()).isEqualTo(today.minusDays(29));
        assertThat(response.clicksPerDay().get(0).count()).isZero();
        assertThat(response.clicksPerDay().get(27).count()).isEqualTo(4L);
        assertThat(response.clicksPerDay().get(29).count()).isEqualTo(3L);
        assertThat(response.topReferrers()).extracting(r -> r.referrer())
                .containsExactly("https://one.example", "https://two.example");
        verify(events).countByLinkId(42L);
        verify(events).countByDay(42L, today.minusDays(29), today);
        verify(events).topReferrers(eq(42L), any(Pageable.class));
        verify(audit).record("ANALYTICS_REQUEST", "ABC1234", null, "SUCCESS");
    }

    @Test
    void auditsAnalyticsNotFoundWithoutRunningEventQueries() {
        when(links.findByCode("MISSING")).thenReturn(Optional.empty());
        when(request.getRemoteAddr()).thenReturn("192.0.2.20");
        LinkAnalyticsService service = new LinkAnalyticsService(links, events, audit, "UTC");

        assertThatThrownBy(() -> service.analytics("MISSING", request))
                .isInstanceOf(LinkNotFoundException.class);

        verify(audit).recordFailure("ANALYTICS_REQUEST", "MISSING", "192.0.2.20", "NOT_FOUND");
        verifyNoInteractions(events);
    }

    @Test
    void auditsAndPropagatesDatabaseErrors() {
        Link link = mock(Link.class);
        when(link.getId()).thenReturn(43L);
        when(links.findByCode("ERR1234")).thenReturn(Optional.of(link));
        RuntimeException failure = new RuntimeException("database failure");
        when(events.countByDay(eq(43L), any(), any())).thenThrow(failure);
