{"files":[{"path":"src/test/java/com/example/shortener/AnalyticsAndValidationIntegrationTest.java","content":"package com.example.shortener;

import com.example.shortener.domain.AuditEvent;
import com.example.shortener.repository.AuditEventRepository;
import com.example.shortener.repository.LinkRepository;
import com.example.shortener.repository.RedirectEventRepository;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.test.system.CapturedOutput;
import org.springframework.boot.test.system.OutputCaptureExtension;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.context.junit.jupiter.EnabledIf;
import org.springframework.test.web.servlet.MockMvc;
import org.junit.jupiter.api.extension.ExtendWith;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest(properties = "app.public-origin=http://localhost:8080")
@AutoConfigureMockMvc
@ExtendWith(OutputCaptureExtension.class)
class AnalyticsAndValidationIntegrationTest {
    @Autowired MockMvc mvc;
    @Autowired LinkRepository links;
    @Autowired RedirectEventRepository redirectEvents;
    @Autowired AuditEventRepository audits;
    @Value("${app.public-origin}") String publicOrigin;

    @Test
    void redirectPersistsTimestampAndRefererAndAnalyticsUsesThirtyDaysAndTopFive() throws Exception {
        String destination = "https://example.com/analytics-" + System.nanoTime();
        String code = create(destination);
        long linkId = links.findByCode(code).orElseThrow().getId();

        for (int i = 0; i < 6; i++) {
            redirect(code, "https://referrer-one.example");
        }
        for (int i = 0; i < 3; i++) {
            redirect(code, "https://referrer-two.example");
        }
        redirect(code, "https://referrer-three.example");
        redirect(code, null);

        assertThat(redirectEvents.countByLinkId(linkId)).isEqualTo(11);
        assertThat(redirectEvents.findAll().stream()
                .filter(event -> event.getLink().getId().equals(linkId)))
                .hasSize(11)
                .allMatch(event -> event.getEventTime() != null && event.getEventDay() != null);
        assertThat(redirectEvents.findAll().stream()
                .filter(event -> event.getLink().getId().equals(linkId))
                .anyMatch(event -> "https://referrer-one.example".equals(event.getReferrer()))).isTrue();
        assertThat(redirectEvents.findAll().stream()
                .filter(event -> event.getLink().getId().equals(linkId))
                .anyMatch(event -> event.getReferrer() == null)).isTrue();

        mvc.perform(get("/api/links/" + code + "/analytics"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(11))
                .andExpect(jsonPath("$.clicksPerDay").isArray())
                .andExpect(jsonPath("$.clicksPerDay.length()").value(30))
                .andExpect(jsonPath("$.topReferrers.length()").value(3))
                .andExpect(jsonPath("$.topReferrers[0].referrer").value("https://referrer-one.example"))
                .andExpect(jsonPath("$.topReferrers[0].count").value(6))
                .andExpect(jsonPath("$.topReferrers[1].count").value(3));
    }

    @Test
    void analyticsNotFoundReturnsExistingProblemAndWritesAudit() throws Exception {
        final String code = "ANL" + Long.toString(System.nanoTime(), 36).substring(0, 4).toUpperCase();
        long before = audits.count();

        mvc.perform(get("/api/links/" + code + "/analytics"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").value("Short link not found"));

        List<AuditEvent> newAudits = audits.findAll().stream().skip(before).toList();
        assertThat(newAudits).anyMatch(a -> "ANALYTICS_REQUEST".equals(a.getAction())
                && code.equals(a.getCode()) && "NOT_FOUND".equals(a.getOutcome())
                && a.getEventTime() != null);
    }

    @Test
    void rejectsConfiguredSelfLinksRegardlessOfIncomingHostAndAuditsRejection() throws Exception {
        long beforeLinks = links.count();
        long beforeAudits = audits.count();
        String selfLink = publicOrigin.replaceAll("/+$", "") + "/ABC1234";

        mvc.perform(post("/api/links").header("Host", "attacker.example")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + selfLink + "\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").value("url must be an absolute HTTP or HTTPS URL"));

        assertThat(links.count()).isEqualTo(beforeLinks);
        assertThat(audits.findAll().stream().skip(beforeAudits))
                .anyMatch(a -> "CREATION_REJECTED".equals(a.getAction())
                        && "SELF_LINK".equals(a.getOutcome()) && a.getEventTime() != null);
    }

    @Test
    void rejectsOverlongDestinationBeforePersistenceAndAuditsLengthReason() throws Exception {
        long beforeLinks = links.count();
        long beforeAudits = audits.count();
        String url = "https://example.com/" + "x".repeat(2030);

        mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").value("url must be an absolute HTTP or HTTPS URL"));

        assertThat(links.count()).isEqualTo(beforeLinks);
        assertThat(audits.findAll().stream().skip(beforeAudits))
                .anyMatch(a -> "CREATION_REJECTED".equals(a.getAction())
                        && "URL_TOO_LONG".equals(a.getOutcome()) && a.getEventTime() != null);
    }

    @Test
    @ExtendWith(OutputCaptureExtension.class)
    void analyticsRequestIsOperationallyLoggedWithoutDestinationDisclosure(CapturedOutput output)
            throws Exception {
        String destination = "https://example.com/analytics-log-" + System.nanoTime();
        String code = create(destination);

        mvc.perform(get("/api/links/" + code + "/analytics"))
                .andExpect(status().isOk());

        assertThat(output.getOut()).contains("ANALYTICS_REQUEST", code, "outcome=SUCCESS")
                .doesNotContain("analytics-log-");
    }

    private String create(String destination) throws Exception {
        String body = mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + destination + "\"}"))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
        return body.replaceAll(".*\\\"code\\\":\\\"([^\\\"]+)\\\".*", "$1");
    }

    private void redirect(String code, String referrer) throws Exception {
        var request = get("/" + code);
        if (referrer != null) {
            request.header("Referer", referrer);
        }
        mvc.perform(request).andExpect(status().isFound());
    }
}
"},{"path":"src/test/java/com/example/shortener/service/LinkAnalyticsServiceTest.java","content":"package com.example.shortener.service;

import com.example.shortener.api.AnalyticsResponse;
import com.example.shortener.domain.Link;
import com.example.shortener.exception.LinkNotFoundException;
import com.example.shortener.repository.LinkRepository;
import com.example.shortener.repository.RedirectEventRepository;
import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.data.domain.Pageable;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class LinkAnalyticsServiceTest {
    @Mock LinkRepository links;
    @Mock RedirectEventRepository events;
    @Mock AuditService audit;
    @Mock HttpServletRequest request;

    @Test
    void aggregatesDatabaseProjectionsIntoThirtyBucketsAndFiveReferrers() {
        Link link = mock(Link.class);
        when(link.getId()).thenReturn(42L);
        when(links.findByCode("ABC1234")).thenReturn(Optional.of(link));
        when(events.countByLinkId(42L)).thenReturn(17L);

        LocalDate today = LocalDate.now();
        RedirectEventRepository.DailyProjection todayRow = daily(today, 3L);
        RedirectEventRepository.DailyProjection olderRow = daily(today.minusDays(2), 4L);
        doReturn(List.of(olderRow, todayRow)).when(events)
                .countByDay(eq(42L), eq(today.minusDays(29)), eq(today));
        doReturn(List.of(referrer("https://one.example", 8L), referrer("https://two.example", 4L)))
                .when(events).topReferrers(eq(42L), any(Pageable.class));

        LinkAnalyticsService service = new LinkAnalyticsService(links, events, audit, "UTC");
        AnalyticsResponse response = service.analytics("ABC1234", request);

        assertThat(response.totalClicks()).isEqualTo(17L);
        assertThat(response.clicksPerDay()).hasSize(30);
        assertThat(response.clicksPerDay().get(0).date()).isEqualTo(today.minusDays(29));
        assertThat(response.clicksPerDay().get(0).count()).isZero();
        assertThat(response.clicksPerDay().get(27).count()).isEqualTo(4L);
        assertThat(response.clicksPerDay().get(29).count()).isEqualTo(3L);
        assertThat(response.topReferrers()).extracting(r -> r.referrer())
                .containsExactly("https://one.example", "https://two.example");
        verify(events).countByLinkId(42L);
        verify(events).countByDay(42L, today.minusDays(29), today);
        verify(events).topReferrers(eq(42L), any(Pageable.class));
        verify(audit).record("ANALYTICS_REQUEST", "ABC1234", null, "SUCCESS");
    }

    @Test
    void auditsAnalyticsNotFoundWithoutRunningEventQueries() {
        when(links.findByCode("MISSING")).thenReturn(Optional.empty());
        when(request.getRemoteAddr()).thenReturn("192.0.2.20");
        LinkAnalyticsService service = new LinkAnalyticsService(links, events, audit, "UTC");

        assertThatThrownBy(() -> service.analytics("MISSING", request))
                .isInstanceOf(LinkNotFoundException.class);

        verify(audit).recordFailure("ANALYTICS_REQUEST", "MISSING", "192.0.2.20", "NOT_FOUND");
        verifyNoInteractions(events);
    }

    @Test
    void auditsAndPropagatesDatabaseErrors() {
        Link link = mock(Link.class);
        when(link.getId()).thenReturn(43L);
        when(links.findByCode("ERR1234")).thenReturn(Optional.of(link));
        RuntimeException failure = new RuntimeException("database failure");
        doReturn(List.of()).when(events).countByDay(eq(43L), any(), any());
        when(events.topReferrers(eq(43L), any(Pageable.class))).thenThrow(failure);
        when(request.getRemoteAddr()).thenReturn("192.0.2.21");
        LinkAnalyticsService service = new LinkAnalyticsService(links, events, audit, "UTC");

        assertThatThrownBy(() -> service.analytics("ERR1234", request)).isSameAs(failure);

        verify(audit).recordFailure("ANALYTICS_REQUEST", "ERR1234", "192.0.2.21", "ERROR");
    }

    @Test
    void invalidAnalyticsCodesAreAuditedAsNotFound() {
        LinkAnalyticsService service = new LinkAnalyticsService(links, events, audit, "UTC");

        assertThatThrownBy(() -> service.analytics("bad", null))
                .isInstanceOf(LinkNotFoundException.class);

        verify(audit).recordFailure("ANALYTICS_REQUEST", "bad", null, "NOT_FOUND");
        verifyNoInteractions(links, events);
    }

    private RedirectEventRepository.DailyProjection daily(LocalDate day, long count) {
        RedirectEventRepository.DailyProjection projection = mock(RedirectEventRepository.DailyProjection.class);
        when(projection.getDay()).thenReturn(day);
        when(projection.getCount()).thenReturn(count);
        return projection;
    }

    private RedirectEventRepository.ReferrerProjection referrer(String value, long count) {
        RedirectEventRepository.ReferrerProjection projection = mock(RedirectEventRepository.ReferrerProjection.class);
        when(projection.getReferrer()).thenReturn(value);
        when(projection.getCount()).thenReturn(count);
        return projection;
    }
}
